(1723088, 233063, 33672, '<td valign="top">Mine too, (until I bought the expresso machine!)</td>', 'Mine too, (until I bought the expresso machine!)', '2005-09-20 02:09:50.000000', NULL, 1),
(1723097, 233106, 41277, '<td valign="top">Excellent gray tone and compose... this is how a b/w photo should look like....<br/>contrast is just right... love it..10</td>', 'Excellent gray tone and compose... this is how a b/w photo should look like....contrast is just right... love it..10', '2005-09-20 02:21:59.000000', NULL, 1),
(1723118, 233290, 15305, '<td valign="top">Magnificent!!  Well managed high key.</td>', 'Magnificent!!  Well managed high key.', '2005-09-20 02:33:50.000000', NULL, 1),
(1723158, 233258, 35545, '<td valign="top">Good use of de-sat.</td>', 'Good use of de-sat.', '2005-09-20 03:21:30.000000', NULL, 1),
(1723160, 233305, 35545, '<td valign="top">Good expression of your concept.  IMHO there''s a little too much foreground.  Try it with the Rule of Thids.  IMHO the composition would benefit by more sky and less foreground which is what the Rule of Thirds would give you.  i like the subdued colors.</td>', 'Good expression of your concept.  IMHO there''s a little too much foreground.  Try it with the Rule of Thids.  IMHO the composition would benefit by more sky and less foreground which is what the Rule of Thirds would give you.  i like the subdued colors.', '2005-09-20 03:23:56.000000', NULL, 1),
(1723162, 231951, 35545, '<td valign="top">I like your idea, but the black, fuzzy things in the foreground overwhelm the picture.</td>', 'I like your idea, but the black, fuzzy things in the foreground overwhelm the picture.', '2005-09-20 03:24:46.000000', NULL, 1),
(1723166, 232996, 35545, '<td valign="top">How did you get them t line up like that.  Great colors, composition, and mood.  My favorite so far.  I wish the boys in the background were in focus, but that''s a minor quibble.</td>', 'How did you get them t line up like that.  Great colors, composition, and mood.  My favorite so far.  I wish the boys in the background were in focus, but that''s a minor quibble.', '2005-09-20 03:29:17.000000', NULL, 1),
(1723170, 233363, 35545, '<td valign="top">Great colors.  Great clouds, too much road in the foreground for my taste, but that''s just me.</td>', 'Great colors.  Great clouds, too much road in the foreground for my taste, but that''s just me.', '2005-09-20 03:31:44.000000', NULL, 1),
(1723178, 231935, 35545, '<td valign="top">I really like the colors and composition, but I think you tried to get too much into the picture.  All of the buildings are too small and I feel like I have to squint to see them.  I like the orange, blue, and white of the buildings against the purplish blue of the mountains.</td>', 'I really like the colors and composition, but I think you tried to get too much into the picture.  All of the buildings are too small and I feel like I have to squint to see them.  I like the orange, blue, and white of the buildings against the purplish blue of the mountains.', '2005-09-20 03:38:24.000000', NULL, 1),
(1723180, 232103, 35545, '<td valign="top">Too much of this picture is out of focus.</td>', 'Too much of this picture is out of focus.', '2005-09-20 03:39:18.000000', NULL, 1),
(1723185, 232955, 35545, '<td valign="top">This has the potential to be a good picture, but I don''t think the blur adds anything to it.  *Something" needs to be in focus.</td>', 'This has the potential to be a good picture, but I don''t think the blur adds anything to it.  *Something" needs to be in focus.', '2005-09-20 03:46:13.000000', NULL, 1),
(1723186, 232911, 35545, '<td valign="top">The picture needs to be bigger so we can see it.  Also the fellow''s black leggings get lost in the dark part of the roof.</td>', 'The picture needs to be bigger so we can see it.  Also the fellow''s black leggings get lost in the dark part of the roof.', '2005-09-20 03:47:23.000000', NULL, 1),
(1723188, 232843, 35545, '<td valign="top">If you like spiders, this is a good picture.  I would have cropped out the reflector in the pavement.</td>', 'If you like spiders, this is a good picture.  I would have cropped out the reflector in the pavement.', '2005-09-20 03:48:33.000000', NULL, 1),
