INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1726425, 233253, 41675, '<td valign="top">Looks nice and peaceful - wish I was there right now. :-)</td>', 'Looks nice and peaceful - wish I was there right now. :-)', '2005-09-21 09:10:59.000000', NULL, 1),
(1726426, 232936, 40579, '<td valign="top">Nice pic but difficult to concentrate</td>', 'Nice pic but difficult to concentrate', '2005-09-21 09:11:15.000000', NULL, 1),
(1726428, 231566, 41675, '<td valign="top">I like the off-centered composition.</td>', 'I like the off-centered composition.', '2005-09-21 09:11:36.000000', NULL, 1),
(1726432, 232718, 40579, '<td valign="top">A bit of over saturation  but a good image</td>', 'A bit of over saturation  but a good image', '2005-09-21 09:13:06.000000', NULL, 1),
(1726434, 233106, 41675, '<td valign="top">For me, the hanger in the back is a bit distracting, but I really like the plane itself and having it in black and white works well for me.</td>', 'For me, the hanger in the back is a bit distracting, but I really like the plane itself and having it in black and white works well for me.', '2005-09-21 09:13:27.000000', NULL, 1),
(1726436, 232899, 41675, '<td valign="top">Nicely done. I think this works well as a black and white.</td>', 'Nicely done. I think this works well as a black and white.', '2005-09-21 09:14:09.000000', NULL, 1),
(1726438, 232024, 40579, '<td valign="top">Fantastic bw good lighting and overall good tones</td>', 'Fantastic bw good lighting and overall good tones', '2005-09-21 09:14:16.000000', NULL, 1),
(1726441, 232232, 40579, '<td valign="top">different and creative way of framing the subject which has been shoot without any viewpoint.<br/>A excellent pic! Great!</td>', 'different and creative way of framing the subject which has been shoot without any viewpoint.A excellent pic! Great!', '2005-09-21 09:16:13.000000', NULL, 1),
(1726443, 233282, 35602, '<td valign="top">The photo is lit very nicely.  Composition is wonderful, with all the curves.  It does seem a little soft on the focus, though.  Did you use a tripod?  Also, when you compressed the image, it created a lot of artifacts (the many different colors which are very apparent on the upper wall)  Here is what I read.  To reduce artifacts, take the image in TIFF format, and as you adjust brightness and contrast, leave it in TIFF.  Do not put in JPEG until you are absolutely sure it is edited as much as you want.  Save only once, unless you need to adjust file to be smaller.  Then submit.</td>', 'The photo is lit very nicely.  Composition is wonderful, with all the curves.  It does seem a little soft on the focus, though.  Did you use a tripod?  Also, when you compressed the image, it created a lot of artifacts (the many different colors which are very apparent on the upper wall)  Here is what I read.  To reduce artifacts, take the image in TIFF format, and as you adjust brightness and contrast, leave it in TIFF.  Do not put in JPEG until you are absolutely sure it is edited as much as you want.  Save only once, unless you need to adjust file to be smaller.  Then submit.', '2005-09-21 09:17:36.000000', NULL, 1),
(1726451, 233363, 35602, '<td valign="top">The image seems to have been oversharpened.  Created a lot of noise in the clouds and a very digital look to the grass in the left foreground.  The image is composed well, though.  The title suits the composition very well.</td>', 'The image seems to have been oversharpened.  Created a lot of noise in the clouds and a very digital look to the grass in the left foreground.  The image is composed well, though.  The title suits the composition very well.', '2005-09-21 09:20:17.000000', NULL, 1),
(1726455, 232990, 41675, '<td valign="top">Nice angle. I like the sky.</td>', 'Nice angle. I like the sky.', '2005-09-21 09:21:43.000000', NULL, 1),
(1726459, 231690, 41675, '<td valign="top">Interesting shot. It tricks my eyes into seeing a tryptich (sp) photo. Creative take on the challenge.</td>', 'Interesting shot. It tricks my eyes into seeing a tryptich (sp) photo. Creative take on the challenge.', '2005-09-21 09:22:34.000000', NULL, 1),
(1726460, 233007, 41675, '<td valign="top">I like it and think it works well in black and white.</td>', 'I like it and think it works well in black and white.', '2005-09-21 09:23:09.000000', NULL, 1),
(1726463, 233311, 41675, '<td valign="top">I like the double imaging of the hand in the mirror.</td>', 'I like the double imaging of the hand in the mirror.', '2005-09-21 09:23:45.000000', NULL, 1),
(1726465, 232648, 35602, '<td valign="top">I like the play of light between the leaves and the ground.  I think it could have been better edited, though.  Colors seem very flat, and it looks like you may have tried burning in the sky, which left a white shadow around the trees, especially on the left.  It also created a lot of grain in the sky.</td>', 'I like the play of light between the leaves and the ground.  I think it could have been better edited, though.  Colors seem very flat, and it looks like you may have tried burning in the sky, which left a white shadow around the trees, especially on the left.  It also created a lot of grain in the sky.', '2005-09-21 09:23:53.000000', NULL, 1),
(1726467, 232015, 41675, '<td valign="top">For me, this might hold more interest if the subject was more off-centered.</td>', 'For me, this might hold more interest if the subject was more off-centered.', '2005-09-21 09:24:53.000000', NULL, 1),
(1726468, 232287, 41675, '<td valign="top">What a cool angle - great capture. Good luck in the challenge. This would have worked well for perspectives too!</td>', 'What a cool angle - great capture. Good luck in the challenge. This would have worked well for perspectives too!', '2005-09-21 09:25:50.000000', NULL, 1),
(1726470, 233258, 35602, '<td valign="top">Reminds me of the movie Pleasantville, when colors started appearing in a black and white landscape.  Liked the effect, and the cars are beautiful.  Nice job of depicting your destination and your title.</td>', 'Reminds me of the movie Pleasantville, when colors started appearing in a black and white landscape.  Liked the effect, and the cars are beautiful.  Nice job of depicting your destination and your title.', '2005-09-21 09:27:03.000000', NULL, 1),
(1726472, 232685, 41675, '<td valign="top">Nice stop action photo. I love the clarity of the foreground wing and the darkness of the water.</td>', 'Nice stop action photo. I love the clarity of the foreground wing and the darkness of the water.', '2005-09-21 09:28:14.000000', NULL, 1),
(1726473, 232443, 35602, '<td valign="top">Excellent composition.</td>', 'Excellent composition.', '2005-09-21 09:28:55.000000', NULL, 1),
(1726475, 233303, 41675, '<td valign="top">Your photo evokes a lonely, solitary feeling in me. I like the composition.</td>', 'Your photo evokes a lonely, solitary feeling in me. I like the composition.', '2005-09-21 09:29:09.000000', NULL, 1),
(1726476, 233001, 41675, '<td valign="top">Pretty scene - such lush green colors. I like the reflection, but I''m surprised it carries into that small area of water.</td>', 'Pretty scene - such lush green colors. I like the reflection, but I''m surprised it carries into that small area of water.', '2005-09-21 09:30:37.000000', NULL, 1),
(1726479, 233282, 41675, '<td valign="top">I like how my eye can travel with the round lines of the photo - from the foreground up and to the windows. For me, I wish the colors were a bit more saturated as they look very rich.</td>', 'I like how my eye can travel with the round lines of the photo - from the foreground up and to the windows. For me, I wish the colors were a bit more saturated as they look very rich.', '2005-09-21 09:31:34.000000', NULL, 1),
(1726482, 232992, 41675, '<td valign="top">This photo appears a little bluish on my monitor, especially the bush in the background. I like the bench and the angle you chose to shoot it at.</td>', 'This photo appears a little bluish on my monitor, especially the bush in the background. I like the bench and the angle you chose to shoot it at.', '2005-09-21 09:34:01.000000', NULL, 1),
(1726485, 233096, 41675, '<td valign="top">I wonder how this would look if you had the chance to shoot even closer to the weather vanes. For me, I think seeing the directionals on them woud have a greater destination impact. I like the concept.</td>', 'I wonder how this would look if you had the chance to shoot even closer to the weather vanes. For me, I think seeing the directionals on them woud have a greater destination impact. I like the concept.', '2005-09-21 09:35:08.000000', NULL, 1),
