(1729108, 231951, 41675, '<td valign="top">Personally, I like this. The softness of the foreground doesn''t bother me at all. In fact, it makes me feel like a little bug on one of the leaves looking up at the moon. Nice job.</td>', 'Personally, I like this. The softness of the foreground doesn''t bother me at all. In fact, it makes me feel like a little bug on one of the leaves looking up at the moon. Nice job.', '2005-09-21 23:26:48.000000', NULL, 1),
(1729115, 233000, 41675, '<td valign="top">I like how the moon is off-centered. I''m still trying to decide if I like the texture of the moon itself...sometimes when I look at it I see crosshatches, then the next moment it kind of reminds me of a newspaper print.</td>', 'I like how the moon is off-centered. I''m still trying to decide if I like the texture of the moon itself...sometimes when I look at it I see crosshatches, then the next moment it kind of reminds me of a newspaper print.', '2005-09-21 23:28:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1729116, 232003, 41675, '<td valign="top">Very cool, graphic photo. I like the overall color values. Good luck in the challenge. 9</td>', 'Very cool, graphic photo. I like the overall color values. Good luck in the challenge. 9', '2005-09-21 23:29:08.000000', NULL, 1),
(1729123, 231087, 41675, '<td valign="top">My first thought was that the sky looks....toxic. For me, the birds add interest and I like the angle.</td>', 'My first thought was that the sky looks....toxic. For me, the birds add interest and I like the angle.', '2005-09-21 23:29:48.000000', NULL, 1),
(1729131, 232955, 41675, '<td valign="top">You may have been going for the blurry look, but I feel like I do when I don''t have my contacts in....nearsighted.</td>', 'You may have been going for the blurry look, but I feel like I do when I don''t have my contacts in....nearsighted.', '2005-09-21 23:30:58.000000', NULL, 1),
(1729134, 233304, 41675, '<td valign="top">Ahhh, very nice photo and colors. I wish I was there right now :-) Good luck in the challenge. 9</td>', 'Ahhh, very nice photo and colors. I wish I was there right now :-) Good luck in the challenge. 9', '2005-09-21 23:31:44.000000', NULL, 1),
(1729135, 233360, 40355, '<td valign="top">Really neat picture.  Deserves contemplation...  Very unique.  Okay, you get the first 10 of this challenge from me!</td>', 'Really neat picture.  Deserves contemplation...  Very unique.  Okay, you get the first 10 of this challenge from me!', '2005-09-21 23:31:56.000000', NULL, 1),
(1729143, 232024, 41675, '<td valign="top">I love the intricacy of the building and statues. I like the coloring you chose, but I bet this would also be quite beautiful in color.</td>', 'I love the intricacy of the building and statues. I like the coloring you chose, but I bet this would also be quite beautiful in color.', '2005-09-21 23:32:56.000000', NULL, 1),
(1729146, 232591, 40355, '<td valign="top">A bit morbid, but its what I thought of when I first saw the challenge.  Well done, love the colors.</td>', 'A bit morbid, but its what I thought of when I first saw the challenge.  Well done, love the colors.', '2005-09-21 23:33:28.000000', NULL, 1),
(1729147, 233284, 41675, '<td valign="top">Your title and photo produced a wry smile. I like the concept. Good use of black and white.</td>', 'Your title and photo produced a wry smile. I like the concept. Good use of black and white.', '2005-09-21 23:33:34.000000', NULL, 1),
(1729149, 232915, 40355, '<td valign="top">Wow...beautiful location!  Very well done, nice and sharp, good composition, contrasty.  A destination I would be happy ending up at! :)</td>', 'Wow...beautiful location!  Very well done, nice and sharp, good composition, contrasty.  A destination I would be happy ending up at! :)', '2005-09-21 23:34:25.000000', NULL, 1),
(1729152, 231707, 41675, '<td valign="top">I wonder how this would look if it was cropped either higher or lower so your horizon line wasn''t in the center of the photo? Sometimes I find that adds a bit more interest. I like the colors, light and the sky reflection. Nicely done. :-)</td>', 'I wonder how this would look if it was cropped either higher or lower so your horizon line wasn''t in the center of the photo? Sometimes I find that adds a bit more interest. I like the colors, light and the sky reflection. Nicely done. :-)', '2005-09-21 23:34:42.000000', NULL, 1),
(1729155, 233001, 40355, '<td valign="top">Beautiful.  Really great composition, love the reflection in the water.  Great lighting and colors...  10</td>', 'Beautiful.  Really great composition, love the reflection in the water.  Great lighting and colors...  10', '2005-09-21 23:35:23.000000', NULL, 1),
(1729158, 233363, 41675, '<td valign="top">I wonder how this would look with a bit more of that dark, menacing cloud cropped off from the top? I like how the "road" leads my eye down and into the photo itself.</td>', 'I wonder how this would look with a bit more of that dark, menacing cloud cropped off from the top? I like how the "road" leads my eye down and into the photo itself.', '2005-09-21 23:35:50.000000', NULL, 1),
(1729160, 233091, 41675, '<td valign="top">What great, vivid colors. I like it. Good luck in the challenge.</td>', 'What great, vivid colors. I like it. Good luck in the challenge.', '2005-09-21 23:36:25.000000', NULL, 1),
(1729163, 233000, 40355, '<td valign="top">Wow...very crisp and sharp!  Very nice moon shot!</td>', 'Wow...very crisp and sharp!  Very nice moon shot!', '2005-09-21 23:36:43.000000', NULL, 1),
(1729167, 232989, 41675, '<td valign="top">Aside from the light spots, nice photo. I like the lower angle you shot this from.</td>', 'Aside from the light spots, nice photo. I like the lower angle you shot this from.', '2005-09-21 23:37:22.000000', NULL, 1),
(1729176, 233362, 41675, '<td valign="top">It took my eyes a moment to realize there was a veiled person on the left hand side. My eyes were totally taken away to the right and bright, out focused area of the photo. My first take was that she was a shadow.</td>', 'It took my eyes a moment to realize there was a veiled person on the left hand side. My eyes were totally taken away to the right and bright, out focused area of the photo. My first take was that she was a shadow.', '2005-09-21 23:38:29.000000', NULL, 1),
(1729180, 232461, 41675, '<td valign="top">For me, I might have cropped out that one bright highlighted cloud at the top, but I like the "neon-like" coloring of the tracks - very cool.</td>', 'For me, I might have cropped out that one bright highlighted cloud at the top, but I like the "neon-like" coloring of the tracks - very cool.', '2005-09-21 23:39:13.000000', NULL, 1),
(1729181, 232055, 40355, '<td valign="top">Very nice.  Like the washed out look of the building in the background and the sharp contrast in the central scene.  give it a cold, final feeling.</td>', 'Very nice.  Like the washed out look of the building in the background and the sharp contrast in the central scene.  give it a cold, final feeling.', '2005-09-21 23:39:21.000000', NULL, 1),
(1729186, 233370, 41675, '<td valign="top">The one thing that catches my eye is the fact that his thumb is right on the line of the road. I wish it was either higher or lower. I like the composition though. (Hope he caught a ride) ;-)</td>', 'The one thing that catches my eye is the fact that his thumb is right on the line of the road. I wish it was either higher or lower. I like the composition though. (Hope he caught a ride) ;-)', '2005-09-21 23:40:29.000000', NULL, 1),
(1729191, 232908, 41675, '<td valign="top">With just a bit more crispness or increased saturation to make it "pop," I would have scored this higher. What a very pretty place though, and I like the composition.</td>', 'With just a bit more crispness or increased saturation to make it "pop," I would have scored this higher. What a very pretty place though, and I like the composition.', '2005-09-21 23:41:40.000000', NULL, 1),
(1729193, 232629, 41675, '<td valign="top">What a beautiful spot. For me, I wonder what this would look like with that bit of rocky shore cropped out on the bottom, but such a beautiful scene.</td>', 'What a beautiful spot. For me, I wonder what this would look like with that bit of rocky shore cropped out on the bottom, but such a beautiful scene.', '2005-09-21 23:42:06.000000', NULL, 1),
(1729252, 233239, 25397, '<td valign="top">Hello Dan, awesome picture! Very creative, as usual. I bet you had fun with this one.<br/>I''ve got an entry in this challenge too :-)</td>', 'Hello Dan, awesome picture! Very creative, as usual. I bet you had fun with this one.I''ve got an entry in this challenge too :-)', '2005-09-21 23:53:31.000000', NULL, 1),
(1729274, 232259, 40355, '<td valign="top">You know, I believe that he just might...   I like the candid-ness of this.  Its a good capture of him in his own raw state.</td>', 'You know, I believe that he just might...   I like the candid-ness of this.  Its a good capture of him in his own raw state.', '2005-09-21 23:58:08.000000', NULL, 1),
(1729293, 232955, 40355, '<td valign="top">Very fuzzy.  To such an extent that without the title, I''d be a bit lost as to what I am looking at.  Low light can be tricky...</td>', 'Very fuzzy.  To such an extent that without the title, I''d be a bit lost as to what I am looking at.  Low light can be tricky...', '2005-09-22 00:03:04.000000', NULL, 1),
(1729297, 233089, 40355, '<td valign="top">Nice B&amp;W.  The shiny chrome makes it great, really nice contrast.</td>', 'Nice B&W.  The shiny chrome makes it great, really nice contrast.', '2005-09-22 00:04:54.000000', NULL, 1),
(1729303, 232497, 40355, '<td valign="top">Beautiful.  really like the lens flare around the sun &amp; the light on the water and cloud edges.</td>', 'Beautiful.  really like the lens flare around the sun & the light on the water and cloud edges.', '2005-09-22 00:07:47.000000', NULL, 1),
(1729388, 232443, 27955, '<td valign="top">This is a beautiful photo, I love the framing of the archways, with everything in focus.</td>', 'This is a beautiful photo, I love the framing of the archways, with everything in focus.', '2005-09-22 00:25:11.000000', NULL, 1),
(1729421, 232461, 40355, '<td valign="top">Really like the way the rails glow in the sun, it''s awesome.  very nice shot</td>', 'Really like the way the rails glow in the sun, it''s awesome.  very nice shot', '2005-09-22 00:37:57.000000', NULL, 1),
(1729511, 233342, 40355, '<td valign="top">Wow...amazing.  Wonderful lighting, focus, composition...everything.  Def a 10!  I only wish I had taken it! :)</td>', 'Wow...amazing.  Wonderful lighting, focus, composition...everything.  Def a 10!  I only wish I had taken it! :)', '2005-09-22 01:05:17.000000', NULL, 1),
(1729724, 232955, 12160, '<td valign="top">I made a pass on this image 4 times just because I''m not sure what to say. What I see is an image that''s OOF everywhere. Not a single thing is in focus and perhaps the photographer is trying to convey something which I fail to understand. It''s definitely using the flaws of technicality to bring out an artistic rendition.<br/> <br/>Let me see.... train in motion, photographer is going home and probably in a rush to do it.<br/>It maybe conveying the thought that this train will take me to my destination (home) but I don;t care about it and I wanna go now immediately (hence the motion blur)<br/> <br/>Okay enough ramblin.... I give you a 7 for artistry.<br/></td>', 'I made a pass on this image 4 times just because I''m not sure what to say. What I see is an image that''s OOF everywhere. Not a single thing is in focus and perhaps the photographer is trying to convey something which I fail to understand. It''s definitely using the flaws of technicality to bring out an artistic rendition. Let me see.... train in motion, photographer is going home and probably in a rush to do it.It maybe conveying the thought that this train will take me to my destination (home) but I don;t care about it and I wanna go now immediately (hence the motion blur) Okay enough ramblin.... I give you a 7 for artistry.', '2005-09-22 02:14:09.000000', NULL, 1),
(1729802, 233106, 18870, '<td valign="top">10!  I love how you framed it.</td>', '10!  I love how you framed it.', '2005-09-22 03:20:37.000000', NULL, 1),
(1729809, 232300, 44357, '<td valign="top">I love the colors and the way they flow in this photo. Wonderful composition.<br/>Uplifting and exquisite.</td>', 'I love the colors and the way they flow in this photo. Wonderful composition.Uplifting and exquisite.', '2005-09-22 03:31:52.000000', NULL, 1),
(1729836, 233239, 23203, '<td valign="top">graphicfunk: you''re the master of multiple exposures.<br/>very well executed.</td>', 'graphicfunk: you''re the master of multiple exposures.very well executed.', '2005-09-22 04:16:03.000000', NULL, 1),
(1729880, 232994, 42792, '<td valign="top">This caught my eye instantly.  I think it''s a great shot with such marvelous colour contrast.  Just don''t get why it''s no destinations ...</td>', 'This caught my eye instantly.  I think it''s a great shot with such marvelous colour contrast.  Just don''t get why it''s no destinations ...', '2005-09-22 06:25:44.000000', NULL, 1),
(1729881, 233243, 42792, '<td valign="top">A really beautiful sillouette shot!</td>', 'A really beautiful sillouette shot!', '2005-09-22 06:27:49.000000', NULL, 1),
(1729882, 233039, 42792, '<td valign="top">Reminds me of a stock photo I had seen.  The subject is surreal but the background is too real.  So it just doesn''t come together for me even tho'' it''s generally a nice pic.</td>', 'Reminds me of a stock photo I had seen.  The subject is surreal but the background is too real.  So it just doesn''t come together for me even tho'' it''s generally a nice pic.', '2005-09-22 06:32:08.000000', NULL, 1),
(1729884, 232785, 42792, '<td valign="top">The skin colour seems a tad artificial.  The angle''s cool.</td>', 'The skin colour seems a tad artificial.  The angle''s cool.', '2005-09-22 06:33:48.000000', NULL, 1),
(1729888, 232718, 42792, '<td valign="top">An awesome take.  Just wondering about the choice to have the cliff focused sharply all the way out - to me it makes the photo a little flat and unreal.  But if that was the intention, I''m zipping up my mouth.</td>', 'An awesome take.  Just wondering about the choice to have the cliff focused sharply all the way out - to me it makes the photo a little flat and unreal.  But if that was the intention, I''m zipping up my mouth.', '2005-09-22 06:39:40.000000', NULL, 1),
(1729926, 233039, 28029, '<td valign="top">Very Clever</td>', 'Very Clever', '2005-09-22 07:13:20.000000', NULL, 1),
(1729930, 231260, 31885, '<td valign="top">Good composition. I think there is a little too much white. The different background tone inside the bracelets looks a little weird.</td>', 'Good composition. I think there is a little too much white. The different background tone inside the bracelets looks a little weird.', '2005-09-22 07:19:17.000000', NULL, 1),
(1729931, 233288, 42792, '<td valign="top">The idea''s pretty humourous but it''s not conveyed very strongly by the photo.  Cloud Nine, for me, is something light, bright, surreal even and maybe paradise-like.  The colours here are very sober.</td>', 'The idea''s pretty humourous but it''s not conveyed very strongly by the photo.  Cloud Nine, for me, is something light, bright, surreal even and maybe paradise-like.  The colours here are very sober.', '2005-09-22 07:19:19.000000', NULL, 1),
(1729932, 233341, 42792, '<td valign="top">Sobering but true.  Not sure about why you chose to focus on the fancy iron rather than the cemetery.</td>', 'Sobering but true.  Not sure about why you chose to focus on the fancy iron rather than the cemetery.', '2005-09-22 07:20:38.000000', NULL, 1),
(1729933, 233350, 31885, '<td valign="top">Beautiful exposure with lovely spread of tones! You should have removed the power lines.</td>', 'Beautiful exposure with lovely spread of tones! You should have removed the power lines.', '2005-09-22 07:21:27.000000', NULL, 1),
(1729964, 232857, 24983, '<td valign="top">this is an excellent shot  I loke the panoramic shape and the little bit of colour is fantastic  10</td>', 'this is an excellent shot  I loke the panoramic shape and the little bit of colour is fantastic  10', '2005-09-22 07:40:54.000000', NULL, 1),
(1730034, 233097, 38925, '<td valign="top">amazing one, i really like the frame</td>', 'amazing one, i really like the frame', '2005-09-22 08:31:41.000000', NULL, 1),
(1730035, 233342, 38925, '<td valign="top">amazing frame</td>', 'amazing frame', '2005-09-22 08:31:53.000000', NULL, 1),
(1730037, 232613, 38925, '<td valign="top">amazing frame, i really like the moment</td>', 'amazing frame, i really like the moment', '2005-09-22 08:32:20.000000', NULL, 1),
(1730039, 231241, 38925, '<td valign="top">it shows, i like it</td>', 'it shows, i like it', '2005-09-22 08:33:30.000000', NULL, 1),
(1730040, 233007, 38925, '<td valign="top">amazing frame, really nice</td>', 'amazing frame, really nice', '2005-09-22 08:33:49.000000', NULL, 1),
(1730042, 232300, 38925, '<td valign="top">amazing frame, i really like it really nice</td>', 'amazing frame, i really like it really nice', '2005-09-22 08:34:19.000000', NULL, 1),
(1730048, 233036, 38925, '<td valign="top">amazing frame, i really like it</td>', 'amazing frame, i really like it', '2005-09-22 08:35:46.000000', NULL, 1),
(1730050, 233106, 38925, '<td valign="top">amazing frame, i really like it. and the lighting woooow</td>', 'amazing frame, i really like it. and the lighting woooow', '2005-09-22 08:36:59.000000', NULL, 1),
(1730054, 232089, 38925, '<td valign="top">amazing frame, i like it</td>', 'amazing frame, i like it', '2005-09-22 08:37:54.000000', NULL, 1),
(1730057, 233288, 38925, '<td valign="top">i like it, amazing frame</td>', 'i like it, amazing frame', '2005-09-22 08:39:25.000000', NULL, 1),
(1730139, 233328, 42470, '<td valign="top">So true, important statement. (nice photo too!)</td>', 'So true, important statement. (nice photo too!)', '2005-09-22 09:09:53.000000', NULL, 1),
(1730142, 233076, 42470, '<td valign="top">Taughonnock NY?  (nice photo)</td>', 'Taughonnock NY?  (nice photo)', '2005-09-22 09:11:29.000000', NULL, 1),
(1730145, 233284, 42470, '<td valign="top">thought provoking...</td>', 'thought provoking...', '2005-09-22 09:14:12.000000', NULL, 1),
(1730214, 232343, 42470, '<td valign="top">GREAT photo..!!!  I hate when dealer''s ruin cars by putting decals on the back - I would have edited that out.  And it would have been awesome if the license plate had a catchy one-word rather than the blur.  I know that would be tough with tight challenge timelines...</td>', 'GREAT photo..!!!  I hate when dealer''s ruin cars by putting decals on the back - I would have edited that out.  And it would have been awesome if the license plate had a catchy one-word rather than the blur.  I know that would be tough with tight challenge timelines...', '2005-09-22 09:33:36.000000', NULL, 1),
(1730344, 233290, 42792, '<td valign="top">Love the ethereal feel to this.  Would love to know how it was done.</td>', 'Love the ethereal feel to this.  Would love to know how it was done.', '2005-09-22 10:35:17.000000', NULL, 1),
(1730346, 233110, 42792, '<td valign="top">Love the angle of the signposts.  Just a little too busy in the back, especially the black bars.</td>', 'Love the angle of the signposts.  Just a little too busy in the back, especially the black bars.', '2005-09-22 10:36:47.000000', NULL, 1),
(1730374, 233349, 42792, '<td valign="top">This image is such a great metaphor for our day and age.  I even like the black line that cuts across - as tho'' to say if we pass it, there''s no going back.  I can just see this photo in The Economist magazine.  Picture-wise, noticed the "burnt" edges of the trees.  Make them look like they''ve been pasted on.  A small detail but wondered what might have caused that.  Also, don''t know if saying the white balance seems a tad off but it looks like that to me.  Still, an 8 for being so "deep". <br/> <br/>;-)</td>', 'This image is such a great metaphor for our day and age.  I even like the black line that cuts across - as tho'' to say if we pass it, there''s no going back.  I can just see this photo in The Economist magazine.  Picture-wise, noticed the "burnt" edges of the trees.  Make them look like they''ve been pasted on.  A small detail but wondered what might have caused that.  Also, don''t know if saying the white balance seems a tad off but it looks like that to me.  Still, an 8 for being so "deep".  ;-)', '2005-09-22 10:52:20.000000', NULL, 1),
(1730380, 233300, 44682, '<td valign="top">Love the picture..wonderful light oppurtunity!</td>', 'Love the picture..wonderful light oppurtunity!', '2005-09-22 10:54:01.000000', NULL, 1),
(1730386, 233186, 42792, '<td valign="top">Love the contrast of the blue as a background for the green - adds a whole interesting aspect to the picture.  The soft light and shin from the pony''s hair gives a great tender moment captured.  Seems to reflect much love of the photographer for this place.</td>', 'Love the contrast of the blue as a background for the green - adds a whole interesting aspect to the picture.  The soft light and shin from the pony''s hair gives a great tender moment captured.  Seems to reflect much love of the photographer for this place.', '2005-09-22 10:55:17.000000', NULL, 1),
(1730396, 232915, 42792, '<td valign="top">I see what you''re getting at with the fence and path, mirroring your title.  But liking the upper half of the image so much, I tried visualizing a crop from where the beach leads out on the right.   I would have liked that a lot better without the shrubs and the wired fence.  The green tones at the far side of the cliff are really something.  Quite beautiful.</td>', 'I see what you''re getting at with the fence and path, mirroring your title.  But liking the upper half of the image so much, I tried visualizing a crop from where the beach leads out on the right.   I would have liked that a lot better without the shrubs and the wired fence.  The green tones at the far side of the cliff are really something.  Quite beautiful.', '2005-09-22 10:59:06.000000', NULL, 1),
(1730404, 231479, 42792, '<td valign="top">Nice but a little too busy.</td>', 'Nice but a little too busy.', '2005-09-22 11:05:50.000000', NULL, 1),
(1730411, 233340, 42792, '<td valign="top">Love the colours and composition.  The train seems a bit odd tho''.  Can''t put a finger on it, sorry.</td>', 'Love the colours and composition.  The train seems a bit odd tho''.  Can''t put a finger on it, sorry.', '2005-09-22 11:09:06.000000', NULL, 1),
(1730430, 233106, 42792, '<td valign="top">Hope not.  But a really nice b&amp;w.</td>', 'Hope not.  But a really nice b&w.', '2005-09-22 11:14:48.000000', NULL, 1),
(1730438, 231360, 42792, '<td valign="top">Like the overall shot a lot.  Small gripe:: assume it''s an umbrella that the girl seems to be holding - just looks like a black patch that leads up to her arm unnaturally.</td>', 'Like the overall shot a lot.  Small gripe:: assume it''s an umbrella that the girl seems to be holding - just looks like a black patch that leads up to her arm unnaturally.', '2005-09-22 11:22:11.000000', NULL, 1),
(1730443, 233304, 29557, '<td valign="top">straight out of a corona commercial</td>', 'straight out of a corona commercial', '2005-09-22 11:24:08.000000', NULL, 1),
(1730445, 231360, 29557, '<td valign="top">haha, awesome!</td>', 'haha, awesome!', '2005-09-22 11:25:40.000000', NULL, 1),
(1730447, 233370, 42792, '<td valign="top">The composition of the road lines makes this photo interesting.  Love the challenge idea too.  What I don''t like is the pinkish tone to the sepia (well assume it is supposed to be sepia).  And I think a slightly tighter crop at the top to get out the mass of dark bush in the upper right could be better.</td>', 'The composition of the road lines makes this photo interesting.  Love the challenge idea too.  What I don''t like is the pinkish tone to the sepia (well assume it is supposed to be sepia).  And I think a slightly tighter crop at the top to get out the mass of dark bush in the upper right could be better.', '2005-09-22 11:26:13.000000', NULL, 1),
(1730866, 233039, 26255, '<td valign="top">Great illusion and I love the colors.  The subject seems a little small and a little too centered on the horizontal.  I would like to see less foreground since it really does nothing to contribute to the overall image and perhaps a slightly tighter crop.  I wouldn''t take anything off the top though.</td>', 'Great illusion and I love the colors.  The subject seems a little small and a little too centered on the horizontal.  I would like to see less foreground since it really does nothing to contribute to the overall image and perhaps a slightly tighter crop.  I wouldn''t take anything off the top though.', '2005-09-22 14:35:56.000000', NULL, 1),
(1730869, 233133, 26255, '<td valign="top">If it wasn''t for the flower in the foreground, this would look very much like a regular snapshot.  The flower adds a much needed element of interest.  I just wish the lighting was a little better on the flower.</td>', 'If it wasn''t for the flower in the foreground, this would look very much like a regular snapshot.  The flower adds a much needed element of interest.  I just wish the lighting was a little better on the flower.', '2005-09-22 14:37:21.000000', NULL, 1),
(1730873, 231951, 26255, '<td valign="top">I like the way you''ve framed the moon, but I''m undecided on how much.  Maybe if the framing was a little darker, it wouldn''t be competing with your main focus so much.</td>', 'I like the way you''ve framed the moon, but I''m undecided on how much.  Maybe if the framing was a little darker, it wouldn''t be competing with your main focus so much.', '2005-09-22 14:38:57.000000', NULL, 1),
(1730878, 233311, 26255, '<td valign="top">Nice crisp image and good composition, but to me it lacks interest.</td>', 'Nice crisp image and good composition, but to me it lacks interest.', '2005-09-22 14:40:02.000000', NULL, 1),
(1730882, 232892, 26255, '<td valign="top">Funny, but IMHO lacks visual interest.  The sky is too bright.</td>', 'Funny, but IMHO lacks visual interest.  The sky is too bright.', '2005-09-22 14:41:13.000000', NULL, 1),
(1730886, 232685, 26255, '<td valign="top">Very crisp image.  I really like this one a lot.  My only nitpicks are the very tip of the left wing is cropped off.  It also seems like the light is coming from in front of the swan.  Maybe a golden yellow hue would give it a warmer look.</td>', 'Very crisp image.  I really like this one a lot.  My only nitpicks are the very tip of the left wing is cropped off.  It also seems like the light is coming from in front of the swan.  Maybe a golden yellow hue would give it a warmer look.', '2005-09-22 14:43:25.000000', NULL, 1),
(1730890, 233370, 26255, '<td valign="top">I like the sepia tones, but the model looks way too posed.  His skin tones look a tad offish (too light).  The placement of the guitar case seems unnatural.</td>', 'I like the sepia tones, but the model looks way too posed.  His skin tones look a tad offish (too light).  The placement of the guitar case seems unnatural.', '2005-09-22 14:45:30.000000', NULL, 1),
(1730894, 233105, 26255, '<td valign="top">OK, I had to flip it to be sure.  Good reflection image.  I''m sorry, but it doesn''t really feel like a "destination" image to me, and that''s only because it''s a reflection.  Perhaps the same image (not reflected) would have more appeal for me on a personal level.</td>', 'OK, I had to flip it to be sure.  Good reflection image.  I''m sorry, but it doesn''t really feel like a "destination" image to me, and that''s only because it''s a reflection.  Perhaps the same image (not reflected) would have more appeal for me on a personal level.', '2005-09-22 14:49:15.000000', NULL, 1),
(1730896, 233076, 26255, '<td valign="top">Looks like a great place to go, but the image seems a little busy to me.  This shot has great potential under much different circumstances.  I would recommend trying this exact same shot in the early morning (right after sunrise) with a much slower shutter speed.  The moving water will have a very soft, magical feel to it.  If you''re lucky, you will have some steam coming off the water and the lighting won''t be so harsh.</td>', 'Looks like a great place to go, but the image seems a little busy to me.  This shot has great potential under much different circumstances.  I would recommend trying this exact same shot in the early morning (right after sunrise) with a much slower shutter speed.  The moving water will have a very soft, magical feel to it.  If you''re lucky, you will have some steam coming off the water and the lighting won''t be so harsh.', '2005-09-22 14:52:28.000000', NULL, 1),
(1731047, 233111, 29474, '<td valign="top">This picture does not convey any sense of ''destination'' to me. It is a strong portrait, and I imagine that people who know her will see alot of her character and (apparent) strength. The heart says give it a higher mark. My voting reality says not.</td>', 'This picture does not convey any sense of ''destination'' to me. It is a strong portrait, and I imagine that people who know her will see alot of her character and (apparent) strength. The heart says give it a higher mark. My voting reality says not.', '2005-09-22 16:15:54.000000', NULL, 1),
