(1732819, 232996, 33696, '<td valign="top">Beutiful picture, the tones and colors are excellent, and the curve of the line they are standing in really makes the picture. I think this is my first or second 10.</td>', 'Beutiful picture, the tones and colors are excellent, and the curve of the line they are standing in really makes the picture. I think this is my first or second 10.', '2005-09-23 06:28:03.000000', NULL, 1),
(1732951, 232461, 16636, '<td valign="top">Excellently exposed and composed image, but I definately would have cropped off the vapour trail at the top, I fear this may loose you votes?</td>', 'Excellently exposed and composed image, but I definately would have cropped off the vapour trail at the top, I fear this may loose you votes?', '2005-09-23 08:25:52.000000', NULL, 1),
