(1733002, 231360, 36606, '<td valign="top">Great photo. Love the angle and composition, with the vibrant colours.  The idea reminds me of Heida''s fantasy image. (10)</td>', 'Great photo. Love the angle and composition, with the vibrant colours.  The idea reminds me of Heida''s fantasy image. (10)', '2005-09-23 08:56:52.000000', NULL, 1),
(1733114, 232304, 4493, '<td valign="top">Simple but very effective. Something about this shot I really like... makes me wonder why I''m being sent to the chair, what room is it in, am I waiting for someone to meet me... I like images that make me think. Good work! -danny</td>', 'Simple but very effective. Something about this shot I really like... makes me wonder why I''m being sent to the chair, what room is it in, am I waiting for someone to meet me... I like images that make me think. Good work! -danny', '2005-09-23 10:16:43.000000', NULL, 1),
(1733144, 232300, 33672, '<td valign="top">Very profound title and image.  Really emotive. I like it. Colors and comp are outstanding.</td>', 'Very profound title and image.  Really emotive. I like it. Colors and comp are outstanding.', '2005-09-23 10:29:29.000000', NULL, 1),
(1733150, 232785, 33672, '<td valign="top">This could of worked in many challenges. Nice capture and comp. Interesting subject matter.</td>', 'This could of worked in many challenges. Nice capture and comp. Interesting subject matter.', '2005-09-23 10:30:46.000000', NULL, 1),
(1733158, 232304, 33672, '<td valign="top">Lighting is almost perfect except for a bit of glare on the chair''s top and a slight shadow on the wall.  Great grasp of theme.</td>', 'Lighting is almost perfect except for a bit of glare on the chair''s top and a slight shadow on the wall.  Great grasp of theme.', '2005-09-23 10:33:47.000000', NULL, 1),
(1733337, 230943, 25742, '<td valign="top">beautiful orange light. good luck</td>', 'beautiful orange light. good luck', '2005-09-23 11:53:27.000000', NULL, 1),
