(1733340, 231867, 25742, '<td valign="top">always difficult to capture this kind of emotional background in a photo. this place is probably special to you, but the photo does not bring that out. with a human element (granny &amp; grandchild) in the forground it might work. better luck next time</td>', 'always difficult to capture this kind of emotional background in a photo. this place is probably special to you, but the photo does not bring that out. with a human element (granny & grandchild) in the forground it might work. better luck next time', '2005-09-23 11:56:17.000000', NULL, 1),
(1733341, 232541, 25742, '<td valign="top">not sure if I get this.</td>', 'not sure if I get this.', '2005-09-23 11:56:35.000000', NULL, 1),
