(1735285, 231566, 32147, '<td valign="top">good shot.   The title really says it all.</td>', 'good shot.   The title really says it all.', '2005-09-24 06:16:07.000000', NULL, 1),
(1735286, 233258, 32147, '<td valign="top">interesting take on "destinations".  Great color control and shot selection.  The way you put this together gives it great feel.</td>', 'interesting take on "destinations".  Great color control and shot selection.  The way you put this together gives it great feel.', '2005-09-24 06:17:44.000000', NULL, 1),
(1735287, 232241, 32147, '<td valign="top">out of focus.  Perhaps that was your intention with this photo, but it doesnt look like the focus was intentional.  If I wanted to soften the focus, I would have used DOF. I would love to see this shot nice and sharp as I am sure that it would be a very powerful image.</td>', 'out of focus.  Perhaps that was your intention with this photo, but it doesnt look like the focus was intentional.  If I wanted to soften the focus, I would have used DOF. I would love to see this shot nice and sharp as I am sure that it would be a very powerful image.', '2005-09-24 06:21:54.000000', NULL, 1),
(1735288, 232287, 32147, '<td valign="top">great composition and use of leading lines!</td>', 'great composition and use of leading lines!', '2005-09-24 06:24:28.000000', NULL, 1),
(1735291, 232296, 32147, '<td valign="top">Perfect!  I love the subject and the composition.  Excellent shot! -10-</td>', 'Perfect!  I love the subject and the composition.  Excellent shot! -10-', '2005-09-24 06:25:26.000000', NULL, 1),
(1735292, 232443, 32147, '<td valign="top">good composition!</td>', 'good composition!', '2005-09-24 06:27:45.000000', NULL, 1),
(1735293, 233087, 32147, '<td valign="top">interesting way to illustrate a good point.  very creative.</td>', 'interesting way to illustrate a good point.  very creative.', '2005-09-24 06:31:51.000000', NULL, 1);
